// src/lib/portfolio.ts
var BLOCKSCOUT = {
  11155111: "https://eth-sepolia.blockscout.com",
  11155420: "https://optimism-sepolia.blockscout.com",
  84532: "https://base-sepolia.blockscout.com",
  4801: "https://worldchain-sepolia.explorer.alchemy.com",
  763373: "https://explorer-sepolia.inkonchain.com",
  1439: "https://testnet.blockscout.injective.network",
  91342: "https://sepolia-explorer.giwa.io",
  46630: "https://explorer.testnet.chain.robinhood.com",
  7080969: "https://humanity-testnet.explorer.alchemy.com",
  98867: "https://testnet-explorer.plume.org",
  1962: "https://testnet.trex.xyz",
  843843: "https://galactica-cassiopeia.explorer.alchemy.com",
  181228: "https://sepolia-explorer.hpp.io",
  681: "https://jasmy-chain-testnet-explorer.alt.technology",
  704852: "https://testnet-explorer.mars-chain.io",
  323432: "https://testnet-explorer.worldmobile.net",
  37714555429: "https://testnet-explorer-v2.xai-chain.net"
};
async function blockscoutTokens(chainId, owner) {
  const base2 = BLOCKSCOUT[chainId];
  if (!base2) return [];
  try {
    const url = `${base2}/api/v2/addresses/${owner}/tokens?type=ERC-20`;
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), 3500);
    const res = await fetch(url, { signal: ctrl.signal });
    clearTimeout(tid);
    if (!res.ok) return [];
    const body = await res.json();
    const items = Array.isArray(body) ? body : body.items ?? [];
    const known = new Set(allTokensForChain(chainId).map((t7) => t7.address.toLowerCase()));
    const out = [];
    for (const h9 of items) {
      const addr = h9.token?.address_hash;
      const sym = h9.token?.symbol;
      const dec = h9.token?.decimals;
      const val = h9.value;
      if (!addr || !sym || dec == null || !val || val === "0") continue;
      if (known.has(addr.toLowerCase())) continue;
      out.push({
        chainId,
        address: addr,
        symbol: sym,
        name: h9.token?.name ?? sym,
        decimals: Number(dec),
        kind: "token",
        color: "#64748b",
        verified: false
      });
    }
    return out;
  } catch {
    return [];
  }
}
async function withTimeout2(p4, ms, label) {
  return Promise.race([
    p4,
    new Promise((_5, rej) => setTimeout(() => rej(new Error(`${label} timed out after ${ms / 1e3}s`)), ms))
  ]);
}
async function loadChain(chainId, owner) {
  const t0 = performance.now();
  const chain = getChain(chainId);
  const client = getPublicClient(wagmiConfig, { chainId });
  if (!client) {
    return { chainId, native: null, nativeError: "no RPC client", tokens: [], ms: 0 };
  }
  const [nativeResult, discovered] = await Promise.all([
    withTimeout2(client.getBalance({ address: owner }), 8e3, "balance").then(
      (v3) => ({ ok: true, value: v3 }),
      (e8) => ({ ok: false, error: e8.message.slice(0, 90) })
    ),
    blockscoutTokens(chainId, owner)
  ]);
  const native = nativeResult.ok ? nativeResult.value : null;
  const nativeError = nativeResult.ok ? void 0 : nativeResult.error;
  const verifiedList = allTokensForChain(chainId).filter(
    // on Arc the ERC-20 USDC entry and the native balance are the same money, show it once
    (t7) => !(chain.nativeIsUsdc && t7.symbol === "USDC")
  );
  const knownAddrs = new Set(verifiedList.map((t7) => t7.address.toLowerCase()));
  const list = [
    ...verifiedList,
    ...discovered.filter((t7) => !knownAddrs.has(t7.address.toLowerCase()))
  ];
  let tokens = [];
  if (list.length > 0) {
    const contracts2 = list.map((t7) => ({
      address: t7.address,
      abi: erc20Abi2,
      functionName: "balanceOf",
      args: [owner]
    }));
    if (chain.nativeIsUsdc && chain.usdc) {
    }
    try {
      const res = await withTimeout2(client.multicall({ contracts: contracts2, allowFailure: true }), 9e3, "multicall");
      tokens = list.map((token, i6) => {
        const r8 = res[i6];
        return r8?.status === "success" ? { token, balance: r8.result } : { token, balance: null, error: "contract did not answer" };
      });
    } catch {
      const settled = await Promise.allSettled(
        list.map(
          (token) => withTimeout2(
            client.readContract({ address: token.address, abi: erc20Abi2, functionName: "balanceOf", args: [owner] }),
            12e3,
            "balanceOf"
          )
        )
      );
      tokens = list.map((token, i6) => {
        const r8 = settled[i6];
        return r8.status === "fulfilled" ? { token, balance: r8.value } : { token, balance: null, error: r8.reason.message.slice(0, 80) };
      });
    }
  }
  return { chainId, native, nativeError, tokens, ms: Math.round(performance.now() - t0) };
}
async function loadPortfolio(owner, opts = {}) {
  const { concurrency = 12, onChain } = opts;
  const ids = CHAINS.map((c7) => c7.id);
  const out = [];
  let cursor = 0;
  async function worker() {
    while (cursor < ids.length) {
      const id = ids[cursor++];
      const holding = await loadChain(id, owner);
      out.push(holding);
      onChain?.(holding);
    }
  }
  await Promise.all(Array.from({ length: Math.min(concurrency, ids.length) }, worker));
  return out.sort((a4, b7) => ids.indexOf(a4.chainId) - ids.indexOf(b7.chainId));
}

// scripts/portfolio-bench.ts
var OWNER = "0x000000000000000000000000000000000000dEaD";
async function run(concurrency) {
  const t0 = Date.now();
  let first = 0;
  let count = 0;
  const res = await loadPortfolio(OWNER, {
    concurrency,
    onChain: () => {
      count += 1;
      if (!first) first = Date.now() - t0;
    }
  });
  const total = Date.now() - t0;
  console.log(
    `concurrency=${concurrency}: first chain ${(first / 1e3).toFixed(2)}s \xB7 ${count} chains \xB7 all ${res.length} done in ${(total / 1e3).toFixed(1)}s`
  );
  return { first, total, count: res.length };
}
var a3 = await run(5);
var b6 = await run(12);
console.log(`first paint improved ${(a3.first / Math.max(b6.first, 1)).toFixed(1)}x`);
